 // Facturación demo. Montos siempre en centavos enteros (ADR-001); facturas emitidas inmutables (ADR-002).

-export const TASA_IVA = 0.13;
+// Tasa de IVA por defecto (RF-002). Se sobrescribe con la variable de entorno TASA_IVA.
+export const TASA_IVA_POR_DEFECTO = 0.13;
+
+// TASA_IVA es un número entre 0 y 1 (p. ej. 0.13). Si no está definida, vale 0.13.
+// Un valor inválido lanza RangeError: no se factura con una tasa que no se pudo leer.
+export function tasaIva(env = process.env) {
+  const crudo = env.TASA_IVA;
+  if (crudo === undefined) return TASA_IVA_POR_DEFECTO;
+  const valor = Number(crudo);
+  if (!/^(\d+(\.\d+)?|\.\d+)$/.test(crudo) || valor < 0 || valor > 1)
+    throw new RangeError(`TASA_IVA inválida: "${crudo}". Debe ser un número entre 0 y 1`);
+  return valor;
+}

